// Put the generated text back on the job (the chain's output replaces the item), keep the binary.
const job = $('Media kind').item.json;
const text = String($input.item.json.text ?? $input.item.json.output ?? '').trim();
if (!text) throw new Error('L’IA n’a renvoyé aucune légende.');
return { json: { ...job, caption: text.slice(0, 2200) }, binary: $('Media kind').item.binary };
